<?php
declare(strict_types=1);

require dirname(__DIR__) . '/auth_store.php';
header('Content-Type: application/json; charset=UTF-8');
header('Cache-Control: no-store, no-cache, must-revalidate');

const TT_TG_BANK_FILE = TT_DATA_DIR . '/accounts.json';
const TT_TG_ACCOUNT_MASTER = __DIR__ . '/../accounts/accounting_master_v1.json';
const TT_TG_FX_MASTER_TYPE = 'tg_currency_rates';

function tgb_out(array $d,int $s=200): never {http_response_code($s);echo json_encode($d,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE);exit;}
function tgb_can(array $u): bool {if(($u['role']??'')==='Super Admin')return true;$p=$u['permissions']['Accounts']??null;if($p==='all')return true;if(!is_array($p))return false;if(in_array('Create',$p,true)||in_array('Edit',$p,true)||in_array('Approve',$p,true))return true;foreach($p as $a)if(is_array($a)&&(in_array('Create',$a,true)||in_array('Edit',$a,true)||in_array('Approve',$a,true)))return true;return false;}
function tgb_store(): array {tt_ensure_data_dir();if(!is_file(TT_TG_BANK_FILE))return ['revision'=>0,'journals'=>[],'bankAccountSettings'=>[],'tgBankTransfers'=>[]];$h=fopen(TT_TG_BANK_FILE,'r');if($h===false||!flock($h,LOCK_SH))throw new RuntimeException('Accounts storage unavailable.');try{$raw=stream_get_contents($h);}finally{flock($h,LOCK_UN);fclose($h);}$v=$raw?json_decode($raw,true):null;return is_array($v)?array_replace_recursive(['revision'=>0,'journals'=>[],'bankAccountSettings'=>[],'tgBankTransfers'=>[]],$v):['revision'=>0,'journals'=>[],'bankAccountSettings'=>[],'tgBankTransfers'=>[]];}
function tgb_catalog(): array {$raw=file_get_contents(TT_TG_ACCOUNT_MASTER);$m=$raw?json_decode($raw,true):null;if(!is_array($m))throw new RuntimeException('Accounting master unavailable.');$out=[];foreach((array)($m['chart']??[]) as $a)if(is_array($a)&&isset($a['code']))$out[(string)$a['code']]=$a;return $out;}
function tgb_entity_from_linked(string $v): string {$u=strtoupper($v);if(str_contains($u,'TG')||str_contains($u,'TRANS GRAINS'))return 'TG';return '';}
function tgb_banks(): array {$m=tt_list_masters();$out=[];foreach((array)($m['banks']??[]) as $r){if(!is_array($r))continue;$v=array_values((array)($r['values']??[]));while(count($v)<14)$v[]='';$id=(string)($r['id']??'');$out[$id]=['id'=>$id,'accountType'=>(string)$v[0],'entity'=>tgb_entity_from_linked((string)$v[1]),'title'=>(string)$v[3],'bank'=>(string)$v[4],'currency'=>strtoupper(trim((string)$v[7])),'accountNumber'=>(string)$v[8],'iban'=>(string)$v[9]];}return $out;}
function tgb_balance(array $store,string $id,string $currency): array {$native=0.0;$aed=0.0;foreach((array)($store['journals']??[]) as $j){if(!is_array($j)||($j['status']??'')!=='Posted'||($j['entity']??'')!=='TG')continue;$jm=is_array($j['meta']??null)?$j['meta']:[];foreach((array)($j['lines']??[]) as $l){if(!is_array($l)||(string)($l['account']??'')!=='1110')continue;$bid=(string)($l['bankAccountId']??$jm['bankAccountId']??'');if($bid!==$id)continue;$native+=(float)($l['bankDebit']??0)-(float)($l['bankCredit']??0);$aed+=(float)($l['debit']??0)-(float)($l['credit']??0);}}if($currency==='AED'&&abs($native)<.0001)$native=$aed;return ['native'=>round($native,4),'aedCarrying'=>round($aed,2),'carryingRate'=>$native>0?round($aed/$native,6):0.0];}
function tgb_rates(string $date): array {$m=tt_list_masters();$rows=(array)($m[TT_TG_FX_MASTER_TYPE]??[]);$best=null;foreach($rows as $r){if(!is_array($r))continue;$v=array_values((array)($r['values']??[]));while(count($v)<12)$v[]='';$status=strtolower((string)$v[10]);if(str_contains($status,'inactive'))continue;$from=(string)$v[6];$to=(string)$v[7];if($from!==''&&$date<$from)continue;if($to!==''&&$date>$to)continue;if($best===null||(string)$v[6]>(string)$best['effectiveFrom'])$best=['id'=>(string)($r['id']??''),'code'=>(string)$v[1],'sellUsdToAed'=>(float)$v[3],'buyUsdWithAed'=>(float)$v[4],'closingTax'=>(float)$v[5],'effectiveFrom'=>$from,'effectiveTo'=>$to,'yearEnd'=>(string)$v[8],'closingCurrency'=>(string)$v[9]];}if(!$best)tgb_out(['ok'=>false,'error'=>'No active TG USD/AED rate set applies to this date.'],422);return $best;}
function tgb_line(string $a,float $dr,float $cr,array $cat,array $x=[]): array {if(!isset($cat[$a]))tgb_out(['ok'=>false,'error'=>'Accounting mapping '.$a.' is unavailable.'],422);return array_merge(['account'=>$a,'accountName'=>(string)($cat[$a]['name']??$a),'debit'=>round($dr,2),'credit'=>round($cr,2)],$x);}
function tgb_next(array $items,string $prefix): string {$n=count($items)+1;do{$id=$prefix.'-'.gmdate('Y').'-'.str_pad((string)$n,6,'0',STR_PAD_LEFT);$n++;}while(isset($items[$id]));return $id;}
function tgb_payload(array $store,string $date): array {$banks=tgb_banks();$rows=[];foreach($banks as $id=>$b){if(($b['entity']??'')!=='TG'||($b['accountType']??'')!=='Company Account'||!in_array($b['currency'],['USD','AED'],true))continue;$s=is_array($store['bankAccountSettings'][$id]??null)?$store['bankAccountSettings'][$id]:[];if(empty($s['active']))continue;$rows[]=array_merge($b,['settings'=>$s,'balance'=>tgb_balance($store,$id,$b['currency'])]);}usort($rows,static fn($a,$b)=>strcmp((string)$a['currency'],(string)$b['currency'])?:strcmp((string)$a['bank'],(string)$b['bank']));$hist=[];foreach((array)($store['tgBankTransfers']??[]) as $x)if(is_array($x))$hist[]=$x;usort($hist,static fn($a,$b)=>strcmp((string)$b['date'],(string)$a['date']));return ['ok'=>true,'entity'=>'TG','rates'=>tgb_rates($date),'banks'=>$rows,'history'=>array_slice($hist,0,30)];}

try{
  $u=tt_require_login();if(!tt_user_can_open_module($u,'Accounts'))tgb_out(['ok'=>false,'error'=>'Accounts permission required.'],403);
  if($_SERVER['REQUEST_METHOD']==='GET'){$date=(string)($_GET['date']??gmdate('Y-m-d'));if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date))$date=gmdate('Y-m-d');tgb_out(tgb_payload(tgb_store(),$date));}
  if($_SERVER['REQUEST_METHOD']!=='POST')tgb_out(['ok'=>false,'error'=>'Method not allowed.'],405);if(!tgb_can($u))tgb_out(['ok'=>false,'error'=>'Accounts Create / Edit / Approve permission required.'],403);
  $b=json_decode(file_get_contents('php://input')?:'{}',true);if(!is_array($b)||!tt_verify_csrf((string)($b['csrf']??'')))tgb_out(['ok'=>false,'error'=>'Your session expired. Refresh and try again.'],419);if((string)($b['action']??'')!=='post_transfer')tgb_out(['ok'=>false,'error'=>'Unknown TG bank-transfer action.'],422);
  $date=trim((string)($b['date']??''));if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date))tgb_out(['ok'=>false,'error'=>'Valid transfer date required.'],422);$dir=strtoupper(trim((string)($b['direction']??'')));if(!in_array($dir,['USD_TO_AED','AED_TO_USD'],true))tgb_out(['ok'=>false,'error'=>'Select USD → AED or AED → USD.'],422);$usd=round((float)($b['usdAmount']??0),2);if($usd<=0)tgb_out(['ok'=>false,'error'=>'USD amount must be greater than zero.'],422);$ref=trim((string)($b['reference']??''));if($ref==='')tgb_out(['ok'=>false,'error'=>'Bank transfer/reference is required.'],422);$notes=trim((string)($b['notes']??''));$sourceId=trim((string)($b['sourceBankId']??''));$destId=trim((string)($b['destinationBankId']??''));if($sourceId===$destId)tgb_out(['ok'=>false,'error'=>'Source and destination bank accounts must be different.'],422);
  tt_ensure_data_dir();$h=fopen(TT_TG_BANK_FILE,'c+');if($h===false||!flock($h,LOCK_EX))throw new RuntimeException('Accounts storage unavailable.');
  try{rewind($h);$raw=stream_get_contents($h);$store=$raw?json_decode($raw,true):null;if(!is_array($store))$store=[];$store=array_replace_recursive(['revision'=>0,'journals'=>[],'bankAccountSettings'=>[],'tgBankTransfers'=>[]],$store);foreach((array)$store['tgBankTransfers'] as $x)if(is_array($x)&&strcasecmp((string)($x['reference']??''),$ref)===0)tgb_out(['ok'=>false,'error'=>'This TG bank transfer reference is already posted.'],409);$banks=tgb_banks();$src=$banks[$sourceId]??null;$dst=$banks[$destId]??null;if(!is_array($src)||!is_array($dst)||($src['entity']??'')!=='TG'||($dst['entity']??'')!=='TG')tgb_out(['ok'=>false,'error'=>'Select valid TG company bank accounts.'],422);$expectedSrc=$dir==='USD_TO_AED'?'USD':'AED';$expectedDst=$dir==='USD_TO_AED'?'AED':'USD';if(($src['currency']??'')!==$expectedSrc||($dst['currency']??'')!==$expectedDst)tgb_out(['ok'=>false,'error'=>'Selected bank currencies do not match the transfer direction.'],422);$ss=(array)($store['bankAccountSettings'][$sourceId]??[]);$ds=(array)($store['bankAccountSettings'][$destId]??[]);if(empty($ss['active'])||empty($ss['allowPayments'])||empty($ds['active'])||empty($ds['allowReceipts']))tgb_out(['ok'=>false,'error'=>'Source must allow payments and destination must allow receipts in Accounts.'],422);$rates=tgb_rates($date);$defaultRate=$dir==='USD_TO_AED'?$rates['sellUsdToAed']:$rates['buyUsdWithAed'];$rate=round((float)($b['rate']??$defaultRate),6);if($rate<=0)tgb_out(['ok'=>false,'error'=>'Valid conversion rate required.'],422);$aed=round($usd*$rate,2);$srcBal=tgb_balance($store,$sourceId,$src['currency']);$need=$dir==='USD_TO_AED'?$usd:$aed;if($need>$srcBal['native']+.01)tgb_out(['ok'=>false,'error'=>'Insufficient '.$src['currency'].' balance. Required '.$src['currency'].' '.number_format($need,2).' but book balance is '.$src['currency'].' '.number_format($srcBal['native'],2).'.'],422);$cat=tgb_catalog();$lines=[];$fx=0.0;if($dir==='USD_TO_AED'){$carryRate=$srcBal['carryingRate'];if($carryRate<=0)tgb_out(['ok'=>false,'error'=>'USD bank has no AED carrying value. Reconcile/open the USD bank balance before converting.'],422);$carry=round($usd*$carryRate,2);$lines[]=tgb_line('1110',$aed,0,$cat,['bankAccountId'=>$destId,'bankName'=>$dst['bank'],'bankAccountTitle'=>$dst['title'],'currency'=>'AED','bankDebit'=>$aed,'bankCredit'=>0]);$lines[]=tgb_line('1110',0,$carry,$cat,['bankAccountId'=>$sourceId,'bankName'=>$src['bank'],'bankAccountTitle'=>$src['title'],'currency'=>'USD','bankDebit'=>0,'bankCredit'=>$usd]);$fx=round($aed-$carry,2);if($fx>0)$lines[]=tgb_line('7100',0,$fx,$cat,['fxDirection'=>'Gain']);elseif($fx<0)$lines[]=tgb_line('7100',abs($fx),0,$cat,['fxDirection'=>'Loss']);}else{$lines[]=tgb_line('1110',$aed,0,$cat,['bankAccountId'=>$destId,'bankName'=>$dst['bank'],'bankAccountTitle'=>$dst['title'],'currency'=>'USD','bankDebit'=>$usd,'bankCredit'=>0]);$lines[]=tgb_line('1110',0,$aed,$cat,['bankAccountId'=>$sourceId,'bankName'=>$src['bank'],'bankAccountTitle'=>$src['title'],'currency'=>'AED','bankDebit'=>0,'bankCredit'=>$aed]);}
    $dr=round(array_sum(array_column($lines,'debit')),2);$cr=round(array_sum(array_column($lines,'credit')),2);if(abs($dr-$cr)>.01)throw new RuntimeException('TG transfer journal did not balance.');$id=tgb_next((array)$store['tgBankTransfers'],'TGFX');$jid=tgb_next((array)$store['journals'],'AUTO');$meta=['tgBankTransferId'=>$id,'direction'=>$dir,'usdAmount'=>$usd,'aedAmount'=>$aed,'rate'=>$rate,'masterRate'=>$defaultRate,'rateMasterId'=>$rates['id'],'rateMasterCode'=>$rates['code'],'closingTaxRate'=>$rates['closingTax'],'sourceBankId'=>$sourceId,'destinationBankId'=>$destId,'fee'=>0,'fxGainLossAed'=>$fx,'notes'=>$notes];$store['journals'][$jid]=['id'=>$jid,'entity'=>'TG','date'=>$date,'sourceType'=>'TG_USD_AED_TRANSFER','reference'=>$ref,'narration'=>'TG own-bank currency conversion '.$dir.' — '.$ref,'lines'=>$lines,'totalDebit'=>$dr,'totalCredit'=>$cr,'status'=>'Posted','meta'=>$meta,'createdAt'=>gmdate('c'),'createdBy'=>(string)($u['full_name']??$u['username']??'Accounts'),'userId'=>(int)($u['id']??0),'reversalOf'=>null];$row=['id'=>$id,'date'=>$date,'direction'=>$dir,'usdAmount'=>$usd,'aedAmount'=>$aed,'rate'=>$rate,'masterRate'=>$defaultRate,'sourceBankId'=>$sourceId,'sourceBank'=>$src['bank'],'destinationBankId'=>$destId,'destinationBank'=>$dst['bank'],'fee'=>0,'journalId'=>$jid,'reference'=>$ref,'notes'=>$notes,'status'=>'Accounts Approved / Posted','createdAt'=>gmdate('c'),'createdBy'=>(string)($u['full_name']??$u['username']??'Accounts')];$store['tgBankTransfers'][$id]=$row;$store['revision']=(int)($store['revision']??0)+1;rewind($h);ftruncate($h,0);fwrite($h,json_encode($store,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR));fflush($h);
  }finally{flock($h,LOCK_UN);fclose($h);}tgb_out(tgb_payload($store,$date)+['transfer'=>$row,'journal'=>$store['journals'][$jid],'revision'=>$store['revision']]);
}catch(Throwable $e){tgb_out(['ok'=>false,'error'=>'The TG USD/AED transfer could not be completed.'],500);}
